param([string]$BackupSet = "")
$ErrorActionPreference = "Stop"
if (-not $BackupSet) {
    $latest = Get-ChildItem "data\backups\sets" -Directory | Sort-Object Name | Select-Object -Last 1
    if (-not $latest) { throw "No backup set found." }
    $BackupSet = $latest.FullName
}
$wsl = "/mnt/c" + $BackupSet.Substring(2).Replace("\","/")
$b64 = ""
wsl.exe -d Ubuntu -u root -- bash -lc "echo $b64 | base64 -d | bash -s -- '$wsl'"
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
